// CAT12/13 - running statistics of the BME280 readings
if (msg.topic === "reset") {
    context.set("stats", {});
    node.status({ fill: "grey", shape: "ring", text: "reset" });
    return null;
}
const d = msg.payload;
if (!d || d.status !== "success") {
    node.status({ fill: "red", shape: "ring", text: "bad reading" });
    return null;
}
const names = {
    temperature: "Temperature (°C)",
    humidity:    "Humidity (%RH)",
    pressure:    "Pressure (hPa)"
};
const s = context.get("stats") || {};
for (const k of Object.keys(names)) {
    const v = Number(d[k]);
    if (!s[k]) s[k] = { min: v, max: v, sum: 0, n: 0 };
    s[k].min = Math.min(s[k].min, v);
    s[k].max = Math.max(s[k].max, v);
    s[k].sum += v;
    s[k].n   += 1;
}
context.set("stats", s);

const rows = Object.keys(names).map(k => ({
    parameter: names[k],
    minimum:   +s[k].min.toFixed(2),
    maximum:   +s[k].max.toFixed(2),
    average:   +(s[k].sum / s[k].n).toFixed(2)
}));
let table = "Parameter            Minimum  Maximum  Average\n";
for (const r of rows) {
    table += r.parameter.padEnd(20) + String(r.minimum).padStart(8) +
             String(r.maximum).padStart(9) + String(r.average).padStart(9) + "\n";
}
node.status({ fill: "green", shape: "dot", text: s.temperature.n + " samples" });
msg.payload = rows;
msg.table = table;
return msg;
